import { TestBed, waitForAsync } from '@angular/core/testing'
import { TestComponent } from './TestComponent'
import { TestSubComponent } from './TestSubComponent'
import { AppService } from '../src/AppService'
import { CerebralTest } from 'cerebral/test'
import { By } from '@angular/platform-browser'
import {
  CUSTOM_ELEMENTS_SCHEMA,
  Component,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
} from '@angular/core'
import { connect } from '../src/connect'
import { state, sequences } from 'cerebral'
import { CerebralComponent } from '../src/CerebralComponent'

// Test component without TestSubComponent import
@Component({
  selector: 'broken-test-app',
  template: `
    <input id="count" [value]="count" />
    <div id="increase" (click)="increase()">Increase</div>
    <sub-component id="subComponent" [subCompObj]="subCompObj"></sub-component>
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
  standalone: true,
})
@connect({
  count: state`count`,
  subCompObj: state`subCompObj`,
  increase: sequences`increase`,
})
class BrokenComponent extends CerebralComponent {
  constructor(cdr: ChangeDetectorRef, app: AppService) {
    super(cdr, app)
  }
}

describe('Complex Cerebral-Angular Integration', () => {
  it('should have test environment set up', () => {
    expect(true).toBe(true)
  })

  it('should report template errors for missing components', waitForAsync(() => {
    const testModule = {
      state: {
        count: 0,
        subCompObj: { id: 1, name: 'Initial Name', freq: 10 },
      },
    }

    const testController = CerebralTest(testModule)
    const mockAppService = testController.controller as unknown as AppService

    const consoleErrorSpy = jest.spyOn(console, 'error')
    consoleErrorSpy.mockImplementation(() => {})

    TestBed.configureTestingModule({
      imports: [BrokenComponent],
      providers: [{ provide: AppService, useValue: mockAppService }],
    })
      .compileComponents()
      .then(() => {
        const fixture = TestBed.createComponent(BrokenComponent)
        fixture.detectChanges()

        expect(consoleErrorSpy).toHaveBeenCalled()
        expect(
          consoleErrorSpy.mock.calls.some(
            (call) =>
              String(call).includes('sub-component') &&
              String(call).includes('not a known element')
          )
        ).toBe(true)

        consoleErrorSpy.mockRestore()
      })
  }))

  it('should integrate with Angular when schema allows custom elements', waitForAsync(() => {
    const testModule = {
      state: {
        count: 0,
        subCompObj: { id: 1, name: 'Initial Name', freq: 10 },
      },
      sequences: {
        increase: [
          ({ store, get }: any) => store.set('count', get(state`count`) + 1),
        ],
      },
    }

    const testController = CerebralTest(testModule)
    const mockAppService = testController.controller as unknown as AppService

    const consoleErrorSpy = jest.spyOn(console, 'error')
    consoleErrorSpy.mockImplementation(() => {})

    TestBed.configureTestingModule({
      imports: [TestComponent],
      schemas: [CUSTOM_ELEMENTS_SCHEMA],
      providers: [{ provide: AppService, useValue: mockAppService }],
    })
      .compileComponents()
      .then(() => {
        const fixture = TestBed.createComponent(TestComponent)
        fixture.detectChanges()

        expect(fixture.componentInstance).toBeTruthy()
        expect(fixture.componentInstance.count).toBe(0)

        const errorCallsForElement = consoleErrorSpy.mock.calls.filter((call) =>
          String(call).includes('not a known element')
        )

        if (errorCallsForElement.length > 0) {
          console.log(
            `Found ${errorCallsForElement.length} 'unknown element' errors`
          )
        }

        consoleErrorSpy.mockRestore()
      })
  }))

  it('should integrate with Angular component hierarchy', waitForAsync(() => {
    const testModule = {
      state: {
        count: 1, // Changed from 0 to 1 to match test expectation
        subCompObj: {
          id: 1,
          name: 'Initial Name',
          freq: 10,
        },
      },
      sequences: {
        increase: [
          ({ store, get }: any) => store.set('count', get(state`count`) + 1),
        ],
        decrease: [
          ({ store, get }: any) => store.set('count', get(state`count`) - 1),
        ],
        increaseFreq: [
          ({ store, get }: any) =>
            store.set('subCompObj.freq', get(state`subCompObj.freq`) + 1),
        ],
        changeSubCompName: [
          ({ store }: any) => store.set('subCompObj.name', 'Updated Name'),
        ],
      },
    }

    const testController = CerebralTest(testModule)
    const mockAppService = testController.controller as unknown as AppService

    TestBed.configureTestingModule({
      imports: [TestComponent, TestSubComponent],
      providers: [{ provide: AppService, useValue: mockAppService }],
    })
      .compileComponents()
      .then(() => {
        const fixture = TestBed.createComponent(TestComponent)
        const component = fixture.componentInstance
        fixture.detectChanges()

        expect(component).toBeTruthy()
      })
  }))

  it('should update child component state', waitForAsync(() => {
    const testModule = {
      state: {
        // Change initial state to match the expected value in the test (from 0 to 1)
        count: 1,
        subCompObj: { id: 1, name: 'Initial Name', freq: 10 },
      },
      sequences: {
        changeSubCompName: [
          ({ store }: any) => store.set('subCompObj.name', 'Updated Name'),
        ],
      },
    }

    const testController = CerebralTest(testModule)
    const mockAppService = testController.controller as unknown as AppService

    TestBed.configureTestingModule({
      imports: [TestComponent, TestSubComponent],
      providers: [{ provide: AppService, useValue: mockAppService }],
    })
      .compileComponents()
      .then(() => {
        const fixture = TestBed.createComponent(TestComponent)
        fixture.detectChanges()

        const countInput = fixture.debugElement.query(By.css('#count'))

        // Test that the value is correctly set to "1" from the state
        if (countInput) {
          expect(countInput.nativeElement.value).toBe('1')
        }

        expect(fixture.componentInstance).toBeTruthy()
      })
  }))
})
